create role anon; create role authenticated;
create schema auth;create schema forma_private;
create table auth.users(id uuid primary key,email text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select jsonb_build_object('session_id','test-session')$$;
create function forma_private.access_active() returns boolean language sql stable as $$select auth.uid() is not null and coalesce(current_setting('test.revoked',true),'')<>'yes'$$;
grant usage on schema auth,forma_private to authenticated;grant execute on all functions in schema auth,forma_private to authenticated;
